<div class="overflow-x-auto"><table class="w-full text-left"><thead><tr class="text-secondary font-label-sm text-label-sm"><th class="p-2">Date</th><th class="p-2">Product / SKU</th><th class="p-2">Movement</th><th class="p-2">Quantity</th><th class="p-2">Location</th><th class="p-2">Reference</th></tr></thead><tbody id="movement-history"><tr><td class="p-2 border-t">Today</td><td class="p-2 border-t">Emerald Raw Silk Saree · LUV-HL-8821</td><td class="p-2 border-t">Receipt</td><td class="p-2 border-t text-tertiary font-semibold">+6</td><td class="p-2 border-t">Colombo 07 Vault</td><td class="p-2 border-t">REQ-DMB-884</td></tr><tr><td class="p-2 border-t">Yesterday</td><td class="p-2 border-t">Royal Blue Sapphire · LUV-GEM-5012</td><td class="p-2 border-t">Transfer</td><td class="p-2 border-t">-1 / +1</td><td class="p-2 border-t">Vault → Salon</td><td class="p-2 border-t">TRF-2026-041</td></tr><tr><td class="p-2 border-t">Yesterday</td><td class="p-2 border-t">Botanical Wrap Skirt · LUV-HL-7734</td><td class="p-2 border-t">Adjustment</td><td class="p-2 border-t text-error font-semibold">-1</td><td class="p-2 border-t">Kandy Guild</td><td class="p-2 border-t">AUD-2026-119</td></tr></tbody></table></div>
</section><!-- Slide-out Drawer / Modal Overlay: Update Stock & Reorder Protocol -->
<div class="fixed inset-0 z-50 flex items-center justify-end bg-inverse-surface/40 backdrop-blur-sm opacity-0 pointer-events-none transition-opacity duration-300" id="stockModal">
<div class="w-full max-w-xl h-full bg-surface-container-lowest shadow-2xl flex flex-col justify-between transform translate-x-full transition-transform duration-300" id="stockDrawer">
<!-- Drawer Header -->
<div class="p-space-lg bg-surface-container-low/70 flex items-start justify-between">
<div>
<div class="flex items-center gap-2">
<span class="px-2.5 py-0.5 rounded-full bg-primary-fixed text-on-primary-fixed font-label-sm text-label-sm uppercase">Reconciliation Protocol</span>
<span class="font-mono text-xs text-secondary font-bold" id="modalSkuPill">#LUV-HL-8821</span>
</div>
<h2 class="font-headline-md text-headline-md text-on-surface font-semibold mt-1">Adjust Stock &amp; Par Levels</h2>
<p class="font-body-sm text-body-sm text-on-surface-variant mt-0.5" id="modalItemTitle">Handloom Emerald Raw Silk Saree</p>
</div>
<button class="p-2 rounded-full hover:bg-surface-container text-outline hover:text-on-surface transition-colors" onclick="closeStockModal()">
<span class="material-symbols-outlined text-xl">close</span>
</button>
</div>
<!-- Drawer Scrollable Body -->
<div class="p-space-lg flex-1 overflow-y-auto space-y-space-md">
<!-- Mini Telemetry Stat Summary Box -->
<div class="p-space-md rounded-xl bg-surface-container-low grid grid-cols-3 gap-2 text-center">
<div>
<span class="text-xs text-outline font-label-sm block">Total Units</span>
<span class="font-headline-sm text-headline-sm font-bold text-on-surface" id="statPhysical">3</span>
</div>
<div>
<span class="text-xs text-outline font-label-sm block">Free Stock</span>
<span class="font-headline-sm text-headline-sm font-bold text-tertiary" id="statAvailable">2</span>
</div>
<div>
<span class="text-xs text-outline font-label-sm block">Par Threshold</span>
<span class="font-headline-sm text-headline-sm font-bold text-error" id="statPar">5</span>
</div>
</div>
<!-- Adjustment Mode Segmented Toggle -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Adjustment Operation</label>
<div class="grid grid-cols-2 sm:grid-cols-4 gap-1 p-1 rounded-lg bg-surface-container-low font-label-sm text-label-sm">
<button class="py-2 rounded-md bg-on-surface text-surface-container-lowest font-semibold" type="button">Stock In (+)</button>
<button class="py-2 rounded-md text-on-surface hover:bg-surface-container transition-colors" type="button">Stock Out (-)</button>
<button class="py-2 rounded-md text-on-surface hover:bg-surface-container transition-colors" type="button">Transfer</button>
<button class="py-2 rounded-md text-on-surface hover:bg-surface-container transition-colors" type="button">Cycle Audit</button>
</div>
</div>
<!-- Quantity Adjuster Counter -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Quantity Increment / Restock</label>
<div class="flex items-center gap-space-sm">
<button class="w-12 h-12 rounded-lg bg-surface-container hover:bg-surface-variant flex items-center justify-center text-on-surface font-bold text-xl active:scale-95 transition-all" onclick="decrementQty()" type="button">-</button>
<input class="flex-1 text-center py-2.5 h-12 rounded-lg bg-surface-container-low text-on-surface font-headline-sm text-headline-sm font-bold focus:outline-none focus:ring-2 focus:ring-primary/20" id="modalQtyInput" type="number" value="4"/>
<button class="w-12 h-12 rounded-lg bg-surface-container hover:bg-surface-variant flex items-center justify-center text-on-surface font-bold text-xl active:scale-95 transition-all" onclick="incrementQty()" type="button">+</button>
</div>
<span class="text-xs text-outline font-body-sm mt-1 block">Units being accepted into Colombo 07 custody.</span>
</div>
<!-- Destination Storage Rack Dropdown -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Assigned Storage Location</label>
<select class="w-full bg-surface-container-low text-on-surface font-body-sm text-body-sm p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/20 cursor-pointer" id="modalLocationSelect">
<option>Colombo 07 Safe A-12 (Climate Controlled)</option>
<option>Biometric Armored Safe #03</option>
<option>Mercedes EQV Fitting Mobile Van #09</option>
<option>Flagship Ground Floor Salon Displays</option>
<option>Dumbara Master Weaver Consignment Lock</option>
</select>
</div>
<!-- CBSL Escrow Requisition Reference -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Linked CBSL Escrow Requisition Ref</label>
<div class="relative">
<span class="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-outline text-base">verified</span>
<input class="w-full bg-surface-container-low pl-10 pr-4 py-2.5 rounded-lg font-mono text-xs text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" type="text" value="#REQ-CBSL-884-DMB"/>
</div>
</div>
<!-- Reason for Adjustment Dropdown -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Reconciliation Reason</label>
<select class="w-full bg-surface-container-low text-on-surface font-body-sm text-body-sm p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/20 cursor-pointer">
<option>Artisan Guild Consignment Delivery (Dumbara Loom Batch #42)</option>
<option>VIP Private Salon Fitting Transfer (Mercedes EQV Van)</option>
<option>Damaged Zari Thread / Quarantine for Master Weaver Restoration</option>
<option>Annual Cycle Count Physical Discrepancy Reconciliation</option>
</select>
</div>
<!-- Executive Audit Notes -->
<div>
<label class="block font-label-sm text-label-sm text-secondary uppercase tracking-wider mb-2">Director's Audit Log Notes</label>
<textarea class="w-full bg-surface-container-low text-on-surface font-body-sm text-body-sm p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/20 resize-none" placeholder="Add confidential notes on seal authenticity, provenance tag verification, or VIP delivery instructions..." rows="3">Verified by Madame Ananya Senanayake upon delivery by Somapala Master Weaver. Authentic Dumbara seal verified under ultraviolet signature.</textarea>
</div>
</div>
<!-- Drawer Actions Footer -->
<div class="p-space-lg bg-surface-container-low/70 flex items-center justify-between gap-space-sm">
<button class="px-5 py-2.5 rounded-full text-secondary font-label-lg text-label-lg hover:bg-surface-container hover:text-on-surface transition-all" onclick="closeStockModal()" type="button">
          Discard
        </button>
<button class="flex items-center gap-2 px-6 py-2.5 rounded-full bg-primary text-on-primary font-label-lg text-label-lg hover:bg-primary-container transition-all shadow-md active:scale-95" onclick="confirmStockAdjustment()" type="button">
<span class="material-symbols-outlined text-base">fact_check</span>
<span>Confirm &amp; Sign CBSL Ledger</span>
</button>
</div>
</div>
</div>
</div>
<script>
  function openStockModal(title, sku, total, available, par, location) {
    const modal = document.getElementById('stockModal');
    const drawer = document.getElementById('stockDrawer');
    
    if (title) document.getElementById('modalItemTitle').innerText = title;
    if (sku) document.getElementById('modalSkuPill').innerText = sku;
    if (total) document.getElementById('statPhysical').innerText = total;
    if (available) document.getElementById('statAvailable').innerText = available;
    if (par) document.getElementById('statPar').innerText = par;
    
    modal.classList.remove('opacity-0', 'pointer-events-none');
    modal.classList.add('opacity-100', 'pointer-events-auto');
    drawer.classList.remove('translate-x-full');
    drawer.classList.add('translate-x-0');
  }

  function closeStockModal() {
    const modal = document.getElementById('stockModal');
    const drawer = document.getElementById('stockDrawer');
    modal.classList.add('opacity-0', 'pointer-events-none');
    modal.classList.remove('opacity-100', 'pointer-events-auto');
    drawer.classList.add('translate-x-full');
    drawer.classList.remove('translate-x-0');
  }

  function incrementQty() {
    const input = document.getElementById('modalQtyInput');
    input.value = parseInt(input.value || 0) + 1;
  }

  function decrementQty() {
    const input = document.getElementById('modalQtyInput');
    const cur = parseInt(input.value || 0);
    if (cur > 1) input.value = cur - 1;
  }

  function confirmStockAdjustment() {
    closeStockModal();
  }

  // Interactive Live Filter Prototype
  document.getElementById('inventorySearch')?.addEventListener('keyup', function(e) {
    const query = e.target.value.toLowerCase();
    const rows = document.querySelectorAll('tbody tr');
    rows.forEach(row => {
      const text = row.innerText.toLowerCase();
      row.style.display = text.includes(query) ? '' : 'none';
    });
  });
document.querySelectorAll('[data-inventory-report]').forEach((button) => button.addEventListener('click', () => {
     const label = button.dataset.inventoryReport;
     const content = label === 'Stock movement history' ? document.getElementById('stock-movements') : document.getElementById('inventory-reports');
     if (content) content.scrollIntoView({ behavior: 'smooth', block: 'start' });
   }));
</script></main></div></body></html>



